/*
 * Audio Uniforms view fixtures — TypeScript mirror of the predev bundle's
 * `chromaticity-planning/ui-predev-bundle-v0.2-beta/views/audio.jsx`
 * `AudioUniformsView` component (the GROUPS / timers / BPM_SINES arrays
 * plus the spectrum heights generated by the bundle's `<Spectrum>`
 * primitive).
 *
 * W17 PR3 posture: HARDCODED frozen-frame fixtures only. The bundle JSX
 * animates these via a `requestAnimationFrame` loop driven by a synthetic
 * `t` accumulator; the W17 port deliberately freezes that visualisation
 * — real-time refresh waits for the audio adapter wiring landing in
 * Phase-3+/4a `EV-INTEGRATION-MATRIX` scope (per docs/26).
 *
 * Per the wireframe-alignment memory
 * (`feedback_wireframes_normative_for_ui_ux.md`), the bundle JSX is the
 * canonical structural reference. Numeric values below are sampled from
 * the bundle's signal generators at a representative `t ≈ 17 s`, the
 * same point the wireframe screenshot
 * (`v0.2-ui-wireframe-screenshots/pulse/audio-uniforms.png`) was captured
 * at — keeping the port visually faithful to the reference rendering.
 *
 * Band tints map to the design-token contract:
 *   bass   → --color-band-bass
 *   mid    → --color-band-mid
 *   midhi  → --color-band-midhi
 *   high   → --color-band-high
 *   full   → --color-band-full
 * The bundle's `--violet` accent for `syn_CurvedTime` maps to
 * `--color-signal-violet`; the muted `TIME` accumulator uses
 * `--color-text-2` since it is the catch-all wall-clock reference.
 */

export type BandKind = 'level' | 'hit' | 'presence';

export interface FrequencyBandBar {
  /** Uniform identifier as it appears in `main.glsl`. */
  readonly key: string;
  /** Bar variant — controls renderer mode (vertical fill / flash / vertical fill). */
  readonly kind: BandKind;
  /** Sampled frame value, normalised 0..1. */
  readonly value: number;
}

export interface FrequencyBand {
  readonly id: string;
  readonly label: string;
  readonly subLabel: string;
  /** CSS variable token name for the band tint. */
  readonly tint: string;
  readonly bars: readonly FrequencyBandBar[];
}

export type TimeUniformId =
  | 'syn_BassTime'
  | 'syn_MidTime'
  | 'syn_MidHighTime'
  | 'syn_HighTime'
  | 'syn_Time'
  | 'syn_CurvedTime'
  | 'TIME';

export interface TimeUniform {
  readonly key: TimeUniformId;
  /** Sampled accumulator value, in seconds. */
  readonly value: number;
  /** Period in seconds for the moving fill modulator (0..1 phase). */
  readonly phase: number;
  readonly tint: string;
}

export type BpmUniformKind = 'scalar' | 'bool' | 'wave' | 'step' | 'saw';

export interface BpmUniform {
  readonly key: string;
  readonly label: string;
  readonly kind: BpmUniformKind;
  /** Display value; pre-formatted to keep the view a pure render. */
  readonly displayValue: string;
  /**
   * Optional sparkline samples (60 points, normalised 0..1) for the
   * non-bool / non-scalar cards. Frozen-frame snapshot of the bundle's
   * 3-second window oscillator.
   */
  readonly sparkline?: readonly number[];
  /** Bool-card LED state, when applicable. */
  readonly ledOn?: boolean;
}

export interface AudioUniformsFixture {
  readonly streamingActive: boolean;
  readonly peakDb: number;
  readonly rmsDb: number;
  readonly source: string;
  /** 64 spectrum bar heights, normalised 0..1. */
  readonly spectrumBars: readonly number[];
  readonly bands: readonly FrequencyBand[];
  readonly timeUniforms: readonly TimeUniform[];
  readonly bpmUniforms: readonly BpmUniform[];
}

/* ----------------------------------------------------------------------------
 * Spectrum bars — 64 values approximating the wireframe's left-loaded mountain
 * profile (low end loud, high end falling off). The bundle's `<Spectrum>`
 * primitive generates these from the same simulated signal table; the port
 * inlines a frozen sample for the static fallback (`prefers-reduced-motion`)
 * and exposes the bundle's per-frame generator below for the W25 live
 * animation pipeline in `AudioUniforms.svelte`.
 * ------------------------------------------------------------------------- */

export const SPECTRUM_BAR_COUNT = 64;

/**
 * Bundle's `<Spectrum>` per-bar signal — clamped to `[0, 1]`. Same formula
 * as `chromaticity-planning/ui-predev-bundle-v0.2-beta/components.jsx`
 * `Spectrum` (lines 297+):
 *
 *   v = pow(1 - f, 0.7) * (0.4 + |sin(t·(1.3 + f·4) + f·9)|·0.6) *
 *       (0.6 + sin(t·7 + f·20)·0.3)
 *
 * `f` is the bar's normalised position `i / N` (so the leftmost bar's `f`
 * is `0` and the rightmost's is just under `1`). `t` is the synthetic time
 * accumulator in seconds.
 */
export function spectrumBarValue(f: number, t: number): number {
  const v =
    Math.pow(1 - f, 0.7) *
    (0.4 + Math.abs(Math.sin(t * (1.3 + f * 4) + f * 9)) * 0.6) *
    (0.6 + Math.sin(t * 7 + f * 20) * 0.3);
  return Math.max(0, Math.min(1, v));
}

const SPECTRUM_BARS: readonly number[] = (() => {
  // Frozen-frame fallback used when `prefers-reduced-motion: reduce`. Sampled
  // at `t = 17 s` so the static page matches the wireframe screenshot.
  const out: number[] = [];
  for (let i = 0; i < SPECTRUM_BAR_COUNT; i++) {
    out.push(spectrumBarValue(i / SPECTRUM_BAR_COUNT, 17));
  }
  return out;
})();

/* ----------------------------------------------------------------------------
 * Sparkline samples — 60-point frozen snapshot of each oscillator's last 3 s.
 * Generated by sampling the bundle's `fn(u)` lambdas at u = -3..0 step
 * 3/59 ≈ 0.0508 (matching the bundle's Sparkline N = 60 / windowSec = 3
 * geometry).
 * ------------------------------------------------------------------------- */

/**
 * Build a 60-point window of `fn` ending at `originSec`. The window covers
 * the previous 3 s; sample `i = 0` is the oldest, sample `i = 59` is the
 * newest. Used for both the frozen-frame fixture (with `originSec = FROZEN_T`)
 * and the live W25 animation pipeline (called per-frame with `originSec = t`).
 */
export function buildSparkline(fn: (u: number) => number, originSec: number): readonly number[] {
  const samples: number[] = [];
  const N = 60;
  const windowSec = 3;
  for (let i = 0; i < N; i++) {
    const u = originSec - windowSec * (1 - i / (N - 1));
    samples.push(Math.max(0, Math.min(1, fn(u))));
  }
  return samples;
}

const FROZEN_T = 17;

const TRI = (u: number): number => (u * 2) % 1;
const SIN_1 = (u: number): number => Math.sin(u * 2 * Math.PI) * 0.5 + 0.5;
const TRI_2 = (u: number): number => u % 1;
const SIN_2 = (u: number): number => Math.sin(u * Math.PI) * 0.5 + 0.5;
const SIN_4 = (u: number): number => Math.sin(u * 0.5 * Math.PI) * 0.5 + 0.5;
const SAW_BEAT = (u: number): number => (u * 2) % 1;
const TWITCH = (u: number): number => Math.cos(u * 4) * 0.5 + 0.5;
const STEP_RAND = (u: number): number => (Math.floor(u * 2) * 0.137) % 1;

/**
 * Per-uniform signal generators for the BPM-card sparklines. Keyed by the
 * uniform identifier (`syn_BPMSin`, `syn_RandomOnBeat`, etc.); the live
 * `AudioUniforms.svelte` $effect calls `buildSparkline(SPARKLINE_GENERATORS[k], t)`
 * each tick to refresh that card's 60-point window.
 */
export const SPARKLINE_GENERATORS: Readonly<Record<string, (u: number) => number>> = {
  syn_RandomOnBeat: STEP_RAND,
  syn_BPMTri: TRI,
  syn_BPMSin: SIN_1,
  syn_BPMTri2: TRI_2,
  syn_BPMSin2: SIN_2,
  syn_BPMSin4: SIN_4,
  syn_BeatTime: SAW_BEAT,
  syn_BPMTwitcher: TWITCH,
};

